import { City as CityData, Player } from '../types';
import { groupIcons } from '../lib/yieldMap';
import { turnsLeft, yieldData } from './lib/cityYields';
import Portal from './Portal';
import Transport from '../Transport';
import FilterableWindow from './FilterableWindow';
import { assetStore } from '../AssetStore';
import currentTileset from '../lib/tilesets';
import { spriteKey } from '../tilesets/TilesetDescriptor';
import { h } from '../lib/html';
import { s } from '@dom111/element';
import { t } from 'i18next';
import { getLabelForBuildable } from './lib/cityBuild';
import { cityName } from './lib/city';
import { escape } from './lib/requirements';
import watchPlayer, { cityRowIds } from './lib/watchPlayer';

const buildCityRow = async (city: CityData): Promise<HTMLElement[]> => {
  const [food, production, trade, research, gold, luxuries] = [
      'Food',
      'Production',
      'Trade',
      'Research',
      'Gold',
      'Luxuries',
    ].map((yieldName) => yieldData(city, yieldName)),
    [
      foodIcon,
      productionIcon,
      tradeIcon,
      researchIcon,
      goldIcon,
      luxuriesIcon,
    ] = await Promise.all(
      ['Food', 'Production', 'Trade', 'Research', 'Gold', 'Luxuries'].map(
        (yieldName) =>
          assetStore
            .shownAtURL(
              spriteKey(currentTileset(), groupIcons[yieldName]),
              currentTileset().ui.icon
            )
            .then((url) => `<img src="${url}">`)
      )
    );

  return [
    s(`<header>${escape(cityName(city))}</header>`),
    s(
      `<div class="growth"><strong>${t('City.size', {
        size: city.growth.size,
      })}</strong> ${foodIcon} ${t('CityStatus.growth', {
        free: food[2],
        total: food[0],
        totals_context: food[0] === food[2] ? 'equal' : 'unequal',
        turns: turnsLeft(city.growth, city.yields, 'Food'),
      })}</div>`
    ),
    s(
      `<div class="build">${productionIcon}  ${t('CityStatus.build', {
        free: production[2],
        total: production[0],
        context: city.build.building ? 'nonempty' : 'empty',
        totals_context: production[0] === production[2] ? 'equal' : 'unequal',
        buildable: getLabelForBuildable(city.build.building),
        build: city.build,
        turns: city.build.building
          ? turnsLeft(city.build, city.yields, 'Production')
          : Infinity,
      })}</div>`
    ),
    s(
      `<div class="yields">${(
        [
          [trade, tradeIcon],
          [research, researchIcon],
          [gold, goldIcon],
          [luxuries, luxuriesIcon],
        ] as [[number, number, number], string][]
      )
        .filter(([[total]]) => total !== 0)
        .map(
          ([[total, , free], icon]) =>
            `${icon} ${t('CityStatus.totals', {
              free,
              total,
              context: free === total ? 'equal' : 'unequal',
            })}`
        )
        .join(', ')}</div>`
    ),
  ];
};

export class CityStatus extends FilterableWindow {
  #cities: CityData[];
  #portal: Portal;
  #unwatch: () => void;

  constructor(player: Player, portal: Portal, transport: Transport) {
    super(t('CityStatus.title'), s('<div class="loading"></div>'), {
      classes: 'city-status',
      rowSelector: 'tr',
    });

    this.#cities = player.cities;
    this.#unwatch = watchPlayer(player, cityRowIds, (player) => {
      this.#cities = player.cities;

      this.update();
    });
    this.#portal = portal;

    this.update();
  }

  close() {
    this.#unwatch();

    return super.close();
  }

  update() {
    Promise.all(this.#cities.map((city) => buildCityRow(city))).then((rows) =>
      super.update(
        s(
          '<table></table>',
          ...rows.map(([name, growth, build, yields], index) => {
            const row = document.createElement('tr');

            row.append(
              ...(
                [
                  [name, 'th'],
                  [growth, 'td'],
                  [build, 'td'],
                  [yields, 'td'],
                ] as [HTMLElement, string][]
              ).map(([element, containerNodeName]) => {
                const container = document.createElement(containerNodeName);

                container.append(element);

                return container;
              })
            );

            return h(row, {
              click: () => this.#portal.openCity(this.#cities[index]),
            });
          })
        )
      )
    );
  }
}

export default CityStatus;
