import {
  Dialogue,
  DiplomacyAction,
  Interactions,
  Player,
  Resolution,
} from '../types';
import instanceOf from './instanceOf';
import { t } from 'i18next';

/** A line of the talks: who said it (`null` for the scene, said by nobody), what they said, and whether it's ours. */
export interface NegotiationLine {
  speaker: string | null;
  text: string;
  own: boolean;
}

// What a step of the talks with another leader says, and what each of the player's answers to it says. Used by the
//  `chooseFromList` receiver (`app/ChoiceHandler.ts`).

// The wording can depend on what kind of proposal it is (a demand for gold or for an advance, say) and on whether
//  it's one of our own choices (#427). i18next's `context` picks `key_own-gold`, or failing that `key` itself: it does
//  not try `key_gold` on the way, so one of our own choices that reads differently for each kind needs a key for each.
export const interactionContext = (
    interaction: Interactions,
    own: boolean
  ): string | undefined => {
    const kind =
      (interaction as { kind?: string }).kind ??
      (interaction as { proposal?: { kind?: string } }).proposal?.kind;

    return (
      [own ? 'own' : null, kind ?? null]
        .filter((part) => part !== null)
        .join('-') || undefined
    );
  },
  interactionLabel = (interaction: Interactions, own = false) => {
    const context = interactionContext(interaction, own);

    if (instanceOf(interaction, 'Dialogue')) {
      return t(`${interaction._}.${(interaction as Dialogue).key}`, {
        interaction,
        defaultValue: interaction._,
        ns: 'diplomacy',
      });
    }

    if (instanceOf(interaction, 'Proposal')) {
      return t(interaction._, {
        context,
        interaction,
        defaultValue: interaction._,
        ns: 'diplomacy',
      });
    }

    if (instanceOf(interaction, 'Resolution')) {
      const { proposal } = interaction as Resolution;

      return t(`Resolution.${proposal._}.${interaction._}`, {
        context,
        interaction,
        defaultValue: interaction._,
        ns: 'diplomacy',
      });
    }

    return t(`Action.${interaction._}`, {
      interaction,
      defaultValue: interaction._,
      ns: 'diplomacy',
    });
  },
  /**
   * Who said `interaction`: its `by`, or for a resolution without one, the player the proposal was made to, who is the
   *  one answering it (#751). `null` when it can't be told.
   */
  speakerOf = (interaction: Interactions | null): Player | null => {
    if (interaction === null) {
      return null;
    }

    // A resolution is an action of its own, by whoever answered; from a save that didn't send it, the one the proposal
    //  was made to.
    if (instanceOf(interaction, 'Resolution')) {
      const resolution = interaction as Resolution;

      return resolution.by ?? resolution.proposal?.for?.[0] ?? null;
    }

    return (interaction as DiplomacyAction).by ?? null;
  },
  /**
   * Whether `interaction` is the scene rather than anyone's words: an emissary arriving ("An emissary from Germany
   *  wishes to speak with you…"), what an exchange took ("In exchange, the Germans take Bronze Working."), or the
   *  hand-over to the player ("You respond..."). Said by nobody (#751).
   */
  narrated = (interaction: Interactions): boolean =>
    instanceOf(interaction, 'Initiate') ||
    instanceOf(interaction, 'AdvanceTaken') ||
    (instanceOf(interaction, 'Dialogue') &&
      (interaction as Dialogue).key === 'handover'),
  /** A player as the talks name them: their leader, or failing one, their nation. */
  playerName = (player: Player): string =>
    player.civilization?.leader
      ? t('Generic.leader-name', {
          leader: player.civilization.leader._,
          player,
        })
      : t('Generic.civilization-name.plural', {
          civilization: player.civilization?._,
          player,
        }),
  /** A line of the talks: who said it, `You` for `us`, and what they said, in our own words where it's ours. */
  negotiationLine = (
    interaction: Interactions,
    us: Player | null
  ): NegotiationLine => {
    const speaker = narrated(interaction) ? null : speakerOf(interaction),
      // Only by id, and only one there is: a player sent without one is nobody's but their own.
      own =
        us?.id !== undefined &&
        speaker?.id !== undefined &&
        speaker.id === us.id;

    return {
      speaker:
        speaker === null
          ? null
          : own
          ? t('Negotiation.you')
          : playerName(speaker),
      text: interactionLabel(interaction, own),
      own,
    };
  };
